canvas.addEventListener('wheel',e=>{if(drag)return;const prefs=controls.get(),zoom=prefs.wheel==='zoom'?!(e.ctrlKey||e.metaKey):(e.ctrlKey||e.metaKey);if(e.shiftKey){e.preventDefault();pan[0]-=e.deltaY;draw();}else if(zoom){e.preventDefault();const r=canvas.getBoundingClientRect(),px=(e.clientX-r.left)*640/r.width,py=(e.clientY-r.top)*640/r.height,old=Number($('zoom').value),next=Math.max(.5,Math.min(3,old*Math.exp(-e.deltaY*.002)));$('zoom').value=next;const actual=Number($('zoom').value);pan=[px-64-(px-64-pan[0])*actual/old,py-64-(py-64-pan[1])*actual/old];draw();}else if(prefs.wheel==='zoom'&&(e.ctrlKey||e.metaKey)){e.preventDefault();window.scrollBy(0,e.deltaY);}},{passive:false});
