let bridgeBusy=false;
const booted=boot();
booted.then(()=>{if(sourceProject.recoveryKey.startsWith('pack:'))original=clone(project);if(window.parent!==window)window.parent.postMessage({type:'sprite-workshop:ready'},location.origin);}).catch(e=>msg('Could not open workshop: '+e.message,true));
window.addEventListener('message',async event=>{
  if(!acceptsParentMessage(event,window.parent,location.origin))return;
  const reply=data=>window.parent.postMessage({...data,requestId:event.data.requestId},location.origin);
  if(bridgeBusy){reply({type:'sprite-workshop:error',message:'Wait for the current project to finish opening.'});return;}
  bridgeBusy=true;
  let previous;
  try{
    await booted;const data=validateBridgeRequest(event.data);
    if(data.type==='sprite-workshop:export'){$('save').click();return;}
    const incoming=validateProject(clone(data.project));
    previous={project,original,key:sourceProject.recoveryKey};
    stop();persist();
    let recovered=null;
    if(db)recovered=await new Promise(resolve=>{const r=db.transaction('projects').objectStore('projects').get(data.recoveryKey);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);});
    if(recovered){try{validateProject(recovered);}catch{recovered=null;}}
    project=recovered||incoming;original=incoming;sourceProject.recoveryKey=data.recoveryKey;
    repairSelection();if(data.poseId&&project.poses[data.poseId])poseId=data.poseId;$('scope').value='pose';repairSelection();
    if(project.editorSettings)controls.set(project.editorSettings);
    const missing=await loadAssets(project);if(missing.length)throw Error('Cannot decode '+missing.length+' project images.');
    undo=[];redo=[];persist();renderAll();
    msg(recovered?'Opened this project’s recovered edits. Save project downloads a portable copy.':'Opened layered project. Save project downloads a portable copy.');
    reply({type:'sprite-workshop:opened',projectId:project.id,poseId,recoveryKey:data.recoveryKey,recovered:!!recovered});
  }catch(error){
    if(previous){project=previous.project;original=previous.original;sourceProject.recoveryKey=previous.key;repairSelection();await loadAssets(project);renderAll();}
    msg(error.message,true);reply({type:'sprite-workshop:error',message:error.message});
  }finally{bridgeBusy=false;}
});
